export class PxlInterpreter {
  parseGridGrammar(code: string): PixelMatrix {
    const ast = tokenizePxl(code);
    return ast.reduce((canvas, cmd) => {
      if (cmd.type === 'PALETTE') canvas.setPalette(cmd.colors);
      if (cmd.type === 'DRAW_RECT') canvas.plotRect(cmd.x, cmd.y, cmd.w, cmd.h);
      return canvas;
    }, new PixelMatrix(32, 32));
  }
}

