use std::collections::BTreeMap;

pub struct SnapshotManager {
    pub snapshots: BTreeMap<String, ProjectSnapshot>,
    pub active_index: usize,
}

impl SnapshotManager {
    pub fn restore_snapshot(&mut self, hash: &str) -> Result<(), String> {
        if let Some(snapshot) = self.snapshots.get(hash) {
            println!("Restoring [{}] -> {}", hash, snapshot.timestamp);
            snapshot.apply_diff_to_working_directory()?;
            Ok(())
        } else {
            Err("Snapshot hash not found".into())
        }
    }
}

